insert into public.traduzioni_ui (namespace, chiave, it, de, fr, en, rm) values
('planning', 'griglia_guida.come_testo', 'Prendi un nome dall''elenco qui sotto, tienilo premuto e portalo dentro la sessione. Puoi prendere un intero gruppo, per esempio «Pulcini», oppure un atleta alla volta. Gli istruttori si portano allo stesso modo. Se preferisci non trascinare, usa il pulsante «Aggiungi persone» sopra la sessione: il risultato è lo stesso.', 'Nimm einen Namen aus der Liste unten, halte ihn gedrückt und zieh ihn in die Einheit. Du kannst eine ganze Gruppe nehmen, zum Beispiel «Pulcini», oder eine Athletin nach der anderen. Trainerinnen und Trainer ziehst du genauso hinein. Wenn du lieber nicht ziehst, nutze die Schaltfläche «Personen hinzufügen» über der Einheit: Das Ergebnis ist dasselbe.', 'Prends un nom dans la liste ci-dessous, garde-le appuyé et amène-le dans la séance. Tu peux prendre un groupe entier, par exemple « Pulcini », ou un athlète à la fois. Les entraîneurs se déplacent de la même façon. Si tu préfères ne pas glisser, utilise le bouton « Ajouter des personnes » au-dessus de la séance : le résultat est le même.', 'Pick a name from the list below, keep it pressed and carry it into the session. You can take a whole group, for example “Pulcini”, or one athlete at a time. Coaches are moved the same way. If you prefer not to drag, use the “Add people” button above the session: the result is the same.', 'Prenda in num da la glista sutvart, tegna el smatgà e al porta en la sesida. Ti pos prender ina gruppa entira, per exempel «Pulcini», u in atlet a la giada. Ils instructurs portas ti a medem moda. Sche ti preferas da betg trair, dovra il buttun «Agiuntar persunas» sur la sesida: il resultat è il medem.'),
('planning', 'griglia_guida.come_breve', 'Per aggiungere qualcuno: tieni premuto un nome dell''elenco e portalo dentro la sessione, oppure usa «Aggiungi persone».', 'Um jemanden hinzuzufügen: Halte einen Namen gedrückt und zieh ihn in die Einheit, oder nutze «Personen hinzufügen».', 'Pour ajouter quelqu''un : garde un nom appuyé et amène-le dans la séance, ou utilise « Ajouter des personnes ».', 'To add someone: keep a name pressed and carry it into the session, or use “Add people”.', 'Per agiuntar insatgi: tegna smatgà in num e al porta en la sesida, u dovra «Agiuntar persunas».'),
('planning', 'griglia_guida.pannello_pulsante', 'Aggiungi persone', 'Personen hinzufügen', 'Ajouter des personnes', 'Add people', 'Agiuntar persunas'),
('planning', 'griglia_guida.pannello_titolo', 'Aggiungi persone', 'Personen hinzufügen', 'Ajouter des personnes', 'Add people', 'Agiuntar persunas'),
('planning', 'griglia_guida.pannello_descrizione', 'Sessione {{sessione}}. Spunta chi vuoi aggiungere e conferma una volta sola.', 'Einheit {{sessione}}. Hake an, wen du hinzufügen willst, und bestätige einmal.', 'Séance {{sessione}}. Coche qui tu veux ajouter et confirme une seule fois.', 'Session {{sessione}}. Tick who you want to add and confirm once.', 'Sesida {{sessione}}. Marca tgi che ti vuls agiuntar e conferma ina giada.'),
('planning', 'griglia_guida.pannello_cerca', 'Cerca per nome', 'Nach Namen suchen', 'Chercher par nom', 'Search by name', 'Tschertgar tenor num'),
('planning', 'griglia_guida.pannello_nessuno', 'Nessun nome corrisponde alla ricerca.', 'Kein Name passt zur Suche.', 'Aucun nom ne correspond à la recherche.', 'No name matches the search.', 'Nagin num na correspunda a la tschertga.'),
