('planning', 'griglia_guida.pannello_conferma_other', 'Aggiungi {{count}} scelte', '{{count}} Auswahlen hinzufügen', 'Ajouter {{count}} choix', 'Add {{count}} selections', 'Agiuntar {{count}} tschernas'),
