('planning', 'griglia_guida.det_vuoto', 'Il gruppo non contiene nessun atleta.', 'Die Gruppe enthält keine Athleten.', 'Le groupe ne contient aucun athlète.', 'The group has no athletes.', 'La gruppa na cuntegna nagin atlet.'),
('planning', 'griglia_guida.det_tutti_conflitto', 'Erano tutti già in una sessione sovrapposta.', 'Alle waren bereits in einer überlappenden Einheit.', 'Tous étaient déjà dans une séance qui se chevauche.', 'All were already in an overlapping session.', 'Tuts eran gia en ina sesida che sa surpona.'),
('planning', 'griglia_guida.det_gia_presenti_one', 'Era già in questa sessione.', 'War bereits in dieser Einheit.', 'Était déjà dans cette séance.', 'Was already in this session.', 'Era gia en questa sesida.'),
('planning', 'griglia_guida.det_gia_presenti_other', 'Erano già tutti in questa sessione ({{count}}).', 'Waren bereits alle in dieser Einheit ({{count}}).', 'Étaient déjà tous dans cette séance ({{count}}).', 'All were already in this session ({{count}}).', 'Eran gia tuts en questa sesida ({{count}}).'),
('planning', 'griglia_guida.det_rifiutato', 'Il salvataggio non è stato accettato: controlla i permessi e riprova.', 'Das Speichern wurde nicht angenommen: Prüfe die Berechtigungen und versuche es nochmals.', 'L''enregistrement n''a pas été accepté : vérifie les autorisations et réessaie.', 'Saving was not accepted: check the permissions and try again.', 'La memorisaziun n''è betg vegnida acceptada: controllescha las permissiuns e emprova anc ina giada.'),
('planning', 'griglia_guida.det_atleti_one', '{{count}} atleta', '{{count}} Athlet/in', '{{count}} athlète', '{{count}} athlete', '{{count}} atlet'),
('planning', 'griglia_guida.det_atleti_other', '{{count}} atleti', '{{count}} Athletinnen und Athleten', '{{count}} athlètes', '{{count}} athletes', '{{count}} atlets'),
('planning', 'griglia_guida.det_conflitto_atleti_one', '{{count}} atleta è già in una sessione sovrapposta.', '{{count}} Athlet/in ist bereits in einer überlappenden Einheit.', '{{count}} athlète est déjà dans une séance qui se chevauche.', '{{count}} athlete is already in an overlapping session.', '{{count}} atlet è gia en ina sesida che sa surpona.'),
('planning', 'griglia_guida.det_conflitto_atleti_other', '{{count}} atleti sono già in una sessione sovrapposta.', '{{count}} Athletinnen und Athleten sind bereits in einer überlappenden Einheit.', '{{count}} athlètes sont déjà dans une séance qui se chevauche.', '{{count}} athletes are already in an overlapping session.', '{{count}} atlets èn gia en ina sesida che sa surpona.'),
('planning', 'griglia_guida.det_sessione_sparita', 'La sessione è stata modificata da un''altra persona: ricarica la pagina.', 'Die Einheit wurde von einer anderen Person geändert: Lade die Seite neu.', 'La séance a été modifiée par une autre personne : recharge la page.', 'The session was changed by someone else: reload the page.', 'La sesida è vegnida midada d''ina autra persuna: chargia da nov la pagina.'),
('planning', 'griglia_guida.det_gruppo_sovrapposto', 'Lo stesso gruppo è già collegato a una sessione sovrapposta.', 'Dieselbe Gruppe ist bereits mit einer überlappenden Einheit verbunden.', 'Le même groupe est déjà lié à une séance qui se chevauche.', 'The same group is already linked to an overlapping session.', 'La medema gruppa è gia colliada cun ina sesida che sa surpona.'),
('planning', 'griglia_guida.det_gruppo_collegato_one', 'Gruppo collegato: {{count}} atleta aggiunto.', 'Gruppe verbunden: {{count}} Athlet/in hinzugefügt.', 'Groupe lié : {{count}} athlète ajouté.', 'Group linked: {{count}} athlete added.', 'Gruppa colliada: {{count}} atlet agiuntà.'),
('planning', 'griglia_guida.det_gruppo_collegato_other', 'Gruppo collegato: {{count}} atleti aggiunti.', 'Gruppe verbunden: {{count}} Athletinnen und Athleten hinzugefügt.', 'Groupe lié : {{count}} athlètes ajoutés.', 'Group linked: {{count}} athletes added.', 'Gruppa colliada: {{count}} atlets agiuntads.'),
('planning', 'griglia_guida.det_gruppo_gia_one', 'Il gruppo era già collegato; elenco aggiornato ({{count}} nuovo).', 'Die Gruppe war bereits verbunden; Liste aktualisiert ({{count}} neu).', 'Le groupe était déjà lié ; liste mise à jour ({{count}} nouveau).', 'The group was already linked; list updated ({{count}} new).', 'La gruppa era gia colliada; glista actualisada ({{count}} nov).'),
('planning', 'griglia_guida.det_gruppo_gia_other', 'Il gruppo era già collegato; elenco aggiornato ({{count}} nuovi).', 'Die Gruppe war bereits verbunden; Liste aktualisiert ({{count}} neu).', 'Le groupe était déjà lié ; liste mise à jour ({{count}} nouveaux).', 'The group was already linked; list updated ({{count}} new).', 'La gruppa era gia colliada; glista actualisada ({{count}} novs).'),
('planning', 'griglia_guida.det_istr_sovrapposto', 'Già impegnato in: {{attivita}}', 'Bereits eingeteilt in: {{attivita}}', 'Déjà occupé dans : {{attivita}}', 'Already busy in: {{attivita}}', 'Gia occupà en: {{attivita}}'),
('planning', 'griglia_guida.det_istr_forzato', 'Fuori dalla disponibilità dichiarata, con il motivo registrato.', 'Ausserhalb der angegebenen Verfügbarkeit, mit gespeichertem Grund.', 'En dehors de la disponibilité déclarée, avec le motif enregistré.', 'Outside the declared availability, with the reason recorded.', 'Ordaifer la disponibilitad declerada, cun il motiv registrà.'),
('planning', 'griglia_guida.det_sconosciuto', 'Voce non riconosciuta.', 'Eintrag nicht erkannt.', 'Élément non reconnu.', 'Item not recognised.', 'Element betg renconuschì.'),
('planning', 'griglia_guida.det_annullato', 'Hai annullato la conferma.', 'Du hast die Bestätigung abgebrochen.', 'Tu as annulé la confirmation.', 'You cancelled the confirmation.', 'Ti has interrut la confermaziun.')
